def run_length_encoding(s: str) -> str:
    """
    Takes a string s and returns its run-length encoded form.
    """
    if len(s) == 0:
        return ""

    encoded_str = []
    current_char = s[0]
    count = 1

    for i in range(1, len(s)):
        if s[i] == current_char:
            count += 1
        else:
            encoded_str.append(f"{current_char}{count}")
            current_char = s[i]
            count = 1

    encoded_str.append(f"{current_char}{count}")  # Append the last counted character

    return ''.join(encoded_str)
